public class PercentEncoderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String thrownBy(String text) {
        try {
            String result = PercentEncoder.decode(text);
            return "returned " + result;
        } catch (IllegalArgumentException e) {
            return "IllegalArgumentException";
        } catch (RuntimeException e) {
            return e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        try {
            check("a space becomes %20", "a%20b", PercentEncoder.encode("a b"));
            check("plus is encoded, not treated as a space", "a%2Bb", PercentEncoder.encode("a+b"));
            check("unreserved characters pass through", "x-y_z.1~",
                    PercentEncoder.encode("x-y_z.1~"));
            check("empty text encodes to empty text", "", PercentEncoder.encode(""));
            check("a two-byte character becomes two groups", "caf%C3%A9",
                    PercentEncoder.encode("caf\u00e9"));
            check("reserved punctuation is encoded in uppercase hex", "a%2Fb%3Fc%3Dd",
                    PercentEncoder.encode("a/b?c=d"));

            check("decode undoes a space", "a b", PercentEncoder.decode("a%20b"));
            check("decode leaves a plain plus alone", "a+b", PercentEncoder.decode("a+b"));
            check("decode rebuilds a two-byte character", "caf\u00e9",
                    PercentEncoder.decode("caf%C3%A9"));
            check("encode then decode is a round trip", "hello world / 100%",
                    PercentEncoder.decode(PercentEncoder.encode("hello world / 100%")));
            check("a non-hex escape is rejected", "IllegalArgumentException", thrownBy("%zz"));
            check("a truncated escape is rejected", "IllegalArgumentException", thrownBy("%4"));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

