import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;

/**
 * TASK: Implement percent-encoding (also called URL encoding) by hand.
 *
 * encode(text):
 *   - the UNRESERVED characters A-Z, a-z, 0-9, '-', '_', '.' and '~' pass
 *     through untouched,
 *   - every other character is encoded as its UTF-8 bytes, each byte written
 *     as '%' followed by TWO UPPERCASE hex digits.
 *   Watch out: a character outside ASCII becomes SEVERAL bytes, so it becomes
 *   several %XX groups. Work on text.getBytes(StandardCharsets.UTF_8), not on chars.
 *
 *     encode("a b")      -> "a%20b"
 *     encode("a+b")      -> "a%2Bb"      ('+' is NOT a space here)
 *     encode("x-y_z.1~") -> "x-y_z.1~"   (all unreserved)
 *
 * decode(text): the reverse. '%' followed by two hex digits becomes that byte;
 *   all other characters are copied as they are ('+' stays a plain '+').
 *   The collected bytes are decoded as UTF-8 at the end.
 *   A '%' that is not followed by two hex digits is an error:
 *   throw new IllegalArgumentException("bad escape").
 *
 *     decode("a%20b") -> "a b"      decode("a+b") -> "a+b"
 *     decode("%zz")   -> throws     decode("%4")  -> throws
 */
public class PercentEncoder {

    private static final String HEX = "0123456789ABCDEF";

    private static boolean isUnreserved(int b) {
        char c = (char) b;
        return (c >= 'A' && c <= 'Z')
                || (c >= 'a' && c <= 'z')
                || (c >= '0' && c <= '9')
                || c == '-' || c == '_' || c == '.' || c == '~';
    }

    public static String encode(String text) {
        StringBuilder sb = new StringBuilder();
        for (byte raw : text.getBytes(StandardCharsets.UTF_8)) {
            int b = raw & 0xFF;
            if (isUnreserved(b)) {
                sb.append((char) b);
            } else {
                sb.append('%').append(HEX.charAt(b >> 4)).append(HEX.charAt(b & 0x0F));
            }
        }
        return sb.toString();
    }

    private static int hexValue(char c) {
        int value = Character.digit(c, 16);
        if (value < 0) {
            throw new IllegalArgumentException("bad escape");
        }
        return value;
    }

    public static String decode(String text) {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        int i = 0;
        while (i < text.length()) {
            char c = text.charAt(i);
            if (c == '%') {
                if (i + 2 >= text.length()) {
                    throw new IllegalArgumentException("bad escape");
                }
                int high = hexValue(text.charAt(i + 1));
                int low = hexValue(text.charAt(i + 2));
                bytes.write((high << 4) + low);
                i += 3;
            } else {
                for (byte raw : String.valueOf(c).getBytes(StandardCharsets.UTF_8)) {
                    bytes.write(raw);
                }
                i++;
            }
        }
        return new String(bytes.toByteArray(), StandardCharsets.UTF_8);
    }
}
